CREATE OR REPLACE FUNCTION addrel()
RETURNS void
LANGUAGE plpgsql
AS $$
DECLARE
    bookid integer;
    refid integer;
    rangeseq integer;
BEGIN
    refid := gen_id(reftable_gen, 1);
    refid := gen_id(reftable_gen, 1);
    rangeseq := gen_id(range_seq_gen, 1);
    rangeseq := gen_id(range_seq_gen, 1);
    rangeseq := gen_id(range_seq_gen, 1);
    rangeseq := gen_id(range_seq_gen, 1);
    rangeseq := gen_id(range_seq_gen, 1);
    refid := gen_id(reftable_gen, 1);
    rangeseq := gen_id(range_seq_gen, 1);
    rangeseq := gen_id(range_seq_gen, 1);
    rangeseq := gen_id(range_seq_gen, 1);
    rangeseq := gen_id(range_seq_gen, 1);
    rangeseq := gen_id(range_seq_gen, 1);
    refid := gen_id(reftable_gen, 1);
    rangeseq := gen_id(range_seq_gen, 1);
    rangeseq := gen_id(range_seq_gen, 1);
    rangeseq := gen_id(range_seq_gen, 1);
    rangeseq := gen_id(range_seq_gen, 1);
    rangeseq := gen_id(range_seq_gen, 1);
    refid := gen_id(reftable_gen, 1);
    rangeseq := gen_id(range_seq_gen, 1);
    rangeseq := gen_id(range_seq_gen, 1);
    rangeseq := gen_id(range_seq_gen, 1);
    rangeseq := gen_id(range_seq_gen, 1);
    rangeseq := gen_id(range_seq_gen, 1);
END;
$$;
